Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
long long INF = 1e18;
long long ans = 0;
vector<long long> dpr;
long long solve(long long n){
	if (n==0) return 0;
	if (n<dpr.size() && dpr[n]) return dpr[n];
	long long lastdif = INF;
	long long x = 1, i=0;
	while (abs(x-n)<=lastdif){
		lastdif = abs(x-n);
		x=x*10+1;
		i++;
	}
	x/=10;
	if (x>n && x/10) {
		if (n<dpr.size())return dpr[n]=min(i+solve(abs(x-n)),i-1+solve(abs(x/10-n)));
		return min(i+solve(abs(x-n)),i-1+solve(abs(x/10-n)));
	}
	if (n<dpr.size())
	return dpr[n]= i+solve(abs(x-n));
	return i+solve(abs(x-n));
}
int main(){
#ifdef NEKROLM
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif
	ios_base::sync_with_stdio(false);
	long long n; cin >> n;
	dpr.resize(1e8);
	cout << solve(n);

	return 0;
}



